package practice
import "sync"
func RunAll(tasks []func() error) []error {
 out:=make([]error,len(tasks)); var wg sync.WaitGroup
 for i,task:=range tasks { if task==nil {continue}; wg.Add(1)
  go func(i int, task func() error){defer wg.Done();out[i]=task()}(i,task)
 }
 wg.Wait();return out
}
```

原理说明：若goroutine启动后才Add，等待方可能先看到计数为0而提前返回。传统模式在启动前Add，任务内defer Done，并保证计数不为负。WaitGroup管理完成计数，不自动传递错误或限制并发。

