package practice
import "encoding/json"
func Snapshot(name string,ready bool)([]byte,error){v:=struct{Name string `json:"name"`;Ready bool `json:"ready"`}{name,ready};return json.Marshal(v)}
```

原理说明：反射不能把它们当普通可设置导出字段使用，即使加json标签也不会按普通字段规则处理。需要对外序列化的字段应按API设计导出或实现明确的自定义编码，不能误以为标签能绕过访问边界。

实操CLI参考：
```go
package main
import("encoding/json";"fmt";"io";"os";"practice")
func run()error{
 raw,err:=io.ReadAll(os.Stdin);if err!=nil{return err};var fields map[string]json.RawMessage
 if err=json.Unmarshal(raw,&fields);err!=nil{return err}
 if len(fields)!=2||fields["name"]==nil||fields["ready"]==nil{return fmt.Errorf("exactly name and ready are required")}
 var name string;var ready bool
 if string(fields["name"])=="null"||string(fields["ready"])=="null"{return fmt.Errorf("null is not allowed")}
 if err=json.Unmarshal(fields["name"],&name);err!=nil{return err};if err=json.Unmarshal(fields["ready"],&ready);err!=nil{return err}
 result,err:=practice.Snapshot(name,ready);if err!=nil{return err};_,err=os.Stdout.Write(append(result,'\n'));return err
}
func main(){if err:=run();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(2)}}
```

