package main
import("bytes";"encoding/json";"flag";"fmt";"os";"os/exec";"practice")
func run()error{
 path:=flag.String("request","","JSON program and args");flag.Parse()
 raw,err:=os.ReadFile(*path);if err!=nil{return err}
 if !json.Valid(raw){return fmt.Errorf("invalid JSON document")}
 var request struct{Program string;Args []string}
 decoder:=json.NewDecoder(bytes.NewReader(raw));decoder.DisallowUnknownFields();if err=decoder.Decode(&request);err!=nil{return err}
 if request.Args==nil{return fmt.Errorf("args array required")}
 command,err:=practice.Command(request.Program,request.Args);if err!=nil{return err}
 raw,err=command.CombinedOutput();code:=0
 if err!=nil{exit,ok:=err.(*exec.ExitError);if !ok{return err};code=exit.ExitCode()}
 return json.NewEncoder(os.Stdout).Encode(map[string]any{"output":string(raw),"code":code})
}
func main(){if err:=run();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(2)}}
