package practice
import("io";"log/slog")
func Audit(w io.Writer,user,event string){slog.New(slog.NewJSONHandler(w,nil)).Info(event,"user",user)}
```

原理说明：明确键值和类型便于查询、关联及统一脱敏，减少解析自然语言的脆弱性；仍需设计稳定字段、级别和敏感数据策略。日志handler阻塞、字段高基数和过量输出仍会影响服务，不能因为用结构化库就取消预算。

实操CLI参考：
```go
package main
import("bufio";"encoding/json";"fmt";"os";"practice")
func run()error{
 scanner:=bufio.NewScanner(os.Stdin);scanner.Buffer(make([]byte,4096),1048576+2)
 records:=[][2]string{}
 for scanner.Scan(){
  if len(scanner.Bytes())>1048576{return fmt.Errorf("line exceeds 1MiB")}
  var fields map[string]json.RawMessage;if err:=json.Unmarshal(scanner.Bytes(),&fields);err!=nil{return err}
  if len(fields)!=2||fields["user"]==nil||fields["event"]==nil{return fmt.Errorf("exactly user and event required")}
  var user,event string
  if string(fields["user"])=="null"||string(fields["event"])=="null"{return fmt.Errorf("null not allowed")}
  if err:=json.Unmarshal(fields["user"],&user);err!=nil{return err};if err:=json.Unmarshal(fields["event"],&event);err!=nil{return err}
  records=append(records,[2]string{user,event})
 }
 if err:=scanner.Err();err!=nil{return err}
 for _,record:=range records{practice.Audit(os.Stdout,record[0],record[1])}
 return nil
}
func main(){if err:=run();err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(2)}}
```

