import("runtime/debug";"sort")
func Modules(info *debug.BuildInfo)[]string{out:=[]string{};if info==nil{return out};for _,d:=range info.Deps{if d==nil{continue};s:=d.Path+"@"+d.Version;if d.Replace!=nil{s+="=>"+d.Replace.Path+"@"+d.Replace.Version};out=append(out,s)};sort.Strings(out);return out}
